sourcesContent:
export type Input = boolean
export function choose(value: Input) {
  return <section data-state={value ? 'yes' : 'no'}><span>{value ? 'hit' : 'miss'}</span><span>fixed</span></section>
}
export function unused() { return <span>unused</span> }
